16	package org.springframework.samples.petclinic.util;
17	
18	import java.util.Map;
19	
20	/**
21	 * Normalizes telephone numbers into <a href="https://en.wikipedia.org/wiki/E.164">E.164</a>
22	 * form. Spaces, dashes and brackets are stripped. A number that already carries a leading
23	 * {@code '+'} keeps its explicit country code; otherwise the Australian country code
24	 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national
25	 * digits. The result must contain between 8 and 15 digits after the {@code '+'}, matching
26	 * the E.164 length rule.
27	 *
28	 * <p>In addition to the overall length rule, the national number (the digits after the
29	 * country code) must have the exact length that country expects: {@code '+61'} (Australia)
30	 * requires 9 national digits and {@code '+1'} (NANP) requires 10. A number carrying one of
31	 * these country codes with the wrong national-number length cannot form valid E.164 and is
32	 * rejected.
33	 *
34	 * <p>The same logic backs both the request-time validator (so a number that cannot form
35	 * valid E.164 is rejected with HTTP 400) and the normalization applied before an
36	 * {@code Owner} is persisted, so the value a client is told about matches the value that
37	 * gets stored and compared for duplicates.
38	 */
39	public final class E164Telephone {
40	
41	    /**
42	     * Country calling code to the exact number of national digits it requires. Order is
43	     * irrelevant: when a number's digits could match more than one code, the longest
44	     * matching code is selected (see {@link #toE164(String)}), so entries may be listed
45	     * in any order.
46	     */
47	    private static final Map<String, Integer> NATIONAL_LENGTH = Map.of(
48	            "61", 9,
49	            "1", 10);
50	
51	    private E164Telephone() {
52	    }
53	
54	    /**
55	     * Convert a raw telephone number to E.164 form, or return {@code null} if it cannot
56	     * form a valid E.164 number.
57	     *
58	     * @param raw the raw telephone number as supplied by the client (may be {@code null})
59	     * @return the normalized {@code +<digits>} string, or {@code null} when invalid
60	     */
61	    public static String toE164(String raw) {
62	        if (raw == null) {
63	            return null;
64	        }
65	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
66	        String digits;
67	        if (cleaned.startsWith("+")) {
68	            String body = cleaned.substring(1);
69	            if (!body.matches("\\d+")) {
70	                return null;
71	            }
72	            digits = body;
73	        }
74	        else {
75	            if (!cleaned.matches("\\d+")) {
76	                return null;
77	            }
78	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
79	            digits = "61" + national;
80	        }
81	        if (digits.length() < 8 || digits.length() > 15) {
82	            return null;
83	        }
84	        String code = longestMatchingCountryCode(digits);
85	        if (code != null && digits.length() - code.length() != NATIONAL_LENGTH.get(code)) {
86	            return null;
87	        }
88	        return "+" + digits;
89	    }
90	
91	    /**
92	     * Format a stored E.164 telephone number for human display as the country calling code,
93	     * a space, then the national digits grouped in threes (e.g. {@code "+61412345678"} becomes
94	     * {@code "+61 412 345 678"}). When the country code is not recognised, the whole set of
95	     * digits after the {@code '+'} is grouped in threes. Returns the input unchanged when it is
96	     * {@code null} or not a well-formed {@code +<digits>} value.
97	     *
98	     * @param e164 a telephone number already normalized to E.164 form
99	     * @return the human-friendly representation
100	     */
101	    public static String toDisplay(String e164) {
102	        if (e164 == null || !e164.startsWith("+")) {
103	            return e164;
104	        }
105	        String digits = e164.substring(1);
106	        if (!digits.matches("\\d+")) {
107	            return e164;
108	        }
109	        String code = longestMatchingCountryCode(digits);
110	        String national = code == null ? digits : digits.substring(code.length());
111	        String grouped = groupInThrees(national);
112	        if (code == null) {
113	            return "+" + grouped;
114	        }
115	        return "+" + code + (grouped.isEmpty() ? "" : " " + grouped);
116	    }
117	
118	    /**
119	     * Group a run of digits into space-separated blocks of three, counting from the left
120	     * (e.g. {@code "412345678"} becomes {@code "412 345 678"}).
121	     */
122	    private static String groupInThrees(String digits) {
123	        StringBuilder sb = new StringBuilder();
124	        for (int i = 0; i < digits.length(); i++) {
125	            if (i > 0 && i % 3 == 0) {
126	                sb.append(' ');
127	            }
128	            sb.append(digits.charAt(i));
129	        }
130	        return sb.toString();
131	    }
132	
133	    /**
134	     * Return the longest known country calling code that {@code digits} starts with, or
135	     * {@code null} if none is known. Selecting the longest match makes the result
136	     * independent of {@link #NATIONAL_LENGTH}'s iteration order even when one code is a
137	     * prefix of another.
138	     */
139	    private static String longestMatchingCountryCode(String digits) {
140	        String match = null;
141	        for (String code : NATIONAL_LENGTH.keySet()) {
142	            if (digits.startsWith(code) && (match == null || code.length() > match.length())) {
143	                match = code;
144	            }
145	        }
146	        return match;
147	    }
148	}
